assign top_pmu_signal_chk_err_mask = reg_dec_data_out[2][2]; //deft: 1'b1
assign lockstep_err_mask       = reg_dec_data_out[2][1]; //deft: 1'b1
assign parity_err_mask         = reg_dec_data_out[2][0]; //deft: 1'b1

//10ch

//110h

//Shadow registers

// register_error
 assign reg_parity_error = (parity_invert_2cycle)? reg_parity_error_and : reg_parity_error_or;
  
  always @(posedge pclk or negedge presetn)
  begin
      if(!presetn) begin
        pd_top_noc_idlereq_time_out_err <= 1'b0; 
   end 
   else begin
        pd_top_noc_idlereq_time_out_err <= ~pd_top_noc_idlereq_time_out_mask & pd_top_noc_idlereq_time_out_status; 
   end
end

  
  always @(posedge pclk or negedge presetn)
  begin
      if(!presetn) begin
        pd_top_bisr_done_time_out_err <= 1'b0; 
   end 
   else begin
        pd_top_bisr_done_time_out_err <= ~pd_top_bisr_done_time_out_mask & pd_top_bisr_done_time_out_status; 
   end
end

  
  always @(posedge pclk or negedge presetn)
  begin
      if(!presetn) begin
        pd_top_bisr_busy_time_out_err <= 1'b0; 
   end 
   else begin
        pd_top_bisr_busy_time_out_err <= ~pd_top_bisr_busy_time_out_mask & pd_top_bisr_busy_time_out_status; 
   end
end

  
  always @(posedge pclk or negedge presetn)
  begin
      if(!presetn) begin
        pd_top_pwr_off_time_out_err <= 1'b0; 
   end 
   else begin
        pd_top_pwr_off_time_out_err <= ~pd_top_pwr_off_time_out_mask & pd_top_pwr_off_time_out_status; 
   end
end

  
  always @(posedge pclk or negedge presetn)
  begin
      if(!presetn) begin
        top_pmu_signal_chk_err <= 1'b0; 
   end 
   else begin
        top_pmu_signal_chk_err <= ~top_pmu_signal_chk_err_mask & top_pmu_signal_chk_err_status; 
   end
end

  
  always @(posedge pclk or negedge presetn)
  begin
      if(!presetn) begin
        lockstep_err <= 1'b0; 
   end 
   else begin
        lockstep_err <= ~lockstep_err_mask & lockstep_err_status; 
   end
end


// mission_int, include SW parity_invert injection

  always @(posedge pclk or negedge presetn)
  begin
      if(!presetn) begin
        mission_int <= 1'b0; 
   end 
   else begin
        mission_int <= ~parity_err_mask & parity_err_status; 
   end
end



//Bus read reg logic
always @(*) begin
  case(paddr[12:2])
//0x0
      REG_CFG0:                     prdata_in = {
                                             cpu_idle_cfg[31:0]};
//0x100
      PASSWORD:                     prdata_in = {
                                             32'h0badbeef};
//0x104
      FUSA_CTRL:                    prdata_in = {
                                             10'h0,
                                             2'h0,
                                             2'h0,
                                             2'h0,
                                             2'h0,
                                             1'h0,
                                             parity_invert,
                                             parity_fault_injection[3:0],
                                             4'h0,
                                             lockstep_fault_injection[1:0],
                                             fault_injection_en,
                                             parity_decoder_enable};
//0x108
      MISSIONINTMASK0:              prdata_in = {
                                             25'h0,
                                             pd_top_noc_idlereq_time_out_mask,
                                             pd_top_bisr_done_time_out_mask,
                                             pd_top_bisr_busy_time_out_mask,
                                             pd_top_pwr_off_time_out_mask,
                                             top_pmu_signal_chk_err_mask,
                                             lockstep_err_mask,
                                             parity_err_mask};
//0x10c
      MISSIONINTSTATUSSET0:         prdata_in = {
                                             25'h0,
                                             1'h0,
                                             1'h0,
                                             1'h0,
                                             1'h0,
                                             1'h0,
                                             1'h0,
                                             1'h0};
//0x110
      MISSIONINTSTATUS0:            prdata_in = {
                                             25'h0,
                                             pd_top_noc_idlereq_time_out_status,
                                             pd_top_bisr_done_time_out_status,
                                             pd_top_bisr_busy_time_out_status,
                                             pd_top_pwr_off_time_out_status,
                                             top_pmu_signal_chk_err_status,
                                             lockstep_err_status,
                                             parity_err_status};
//shadow register read
      default: prdata_in = 32'h0;
  endcase
end

always @(posedge pclk or negedge presetn) begin
  if (!presetn) begin
    prdata               <= 32'h0;
  end else if(apb_rd) begin
    prdata               <= prdata_in;
  end
end

assign pready  = 1'b1;
assign pslverr = 1'b0;





